def euclidean_dist(a, b):
    da = a[0] - b[0]
    db = a[1] - b[1]
    return math.sqrt(da*da + db*db)

# Re-analyze Demo 1 with MINIMUM winner hypothesis

sources_d1 = {
    (1, 4): 3,
    (2, 2): 2, (2, 3): 1, (2, 5): 4,
    (3, 2): 2, (3, 5): 4,
}

def min_winning_color(pos, sources):
    """Find nearest source(s), return MINIMUM color among winners"""
    best_d = float('inf')
    best_colors = []
    for s, c in sources.items():
        d = euclidean_dist(pos, s)
        if d < best_d:
            best_d = d
            best_colors = [c]
        elif d == best_d:
            best_colors.append(c)
    return min(best_colors)

