    """Get set of all colors claimed by region, return MINIMUM"""
    colors = set()
    for r, c in cells:
        winner_color = min_winning_color((r,c), sources)
        colors.add(winner_color)
    # Return the min of all colors claimed anywhere in region
    return min(colors), len(colors)

